@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <label>
                Min:
                <input type="number" step="0.01" min="0" @bind="minPrice" class="price-input" />
            </label>
            <label>
                Max:
                <input type="number" step="0.01" min="0" @bind="maxPrice" class="price-input" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-status">Loading products...</div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-status error">@errorMessage</div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-status">No products found.</div>
        }
        else
        {
            <div class="catalog-toolbar">
                <select class="sort-dropdown" @onchange="OnSortChanged">
                    <option value="price_asc" selected="@(sortBy == "price_asc")">Price: Low to High</option>
                    <option value="price_desc" selected="@(sortBy == "price_desc")">Price: High to Low</option>
                    <option value="name_asc" selected="@(sortBy == "name_asc")">Name: A-Z</option>
                    <option value="rating_desc" selected="@(sortBy == "rating_desc")">Rating: Highest</option>
                </select>

                <span class="showing-label">
                    Showing @((result.Page - 1) * result.PageSize + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount)) of @result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="OnProductSelected"
                                 OnAddToCart="OnAddToCart" />
                }
            </div>

            <div class="pagination">
                <button class="btn btn-page" disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn btn-page @(pageNum == currentPage ? "active" : "")"
                            @onclick="() => GoToPage(pageNum)">@pageNum</button>
                }

                <button class="btn btn-page" disabled="@(currentPage >= totalPages)" @onclick="NextPage">Next</button>
            </div>
        }
    </main>
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalPages = 1;
    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            categories = await ProductService.GetCategoriesAsync();
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
            totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
            if (totalPages < 1) totalPages = 1;
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchProducts();
    }

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await SearchProducts();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < totalPages)
        {
            currentPage++;
            await SearchProducts();
        }
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await SearchProducts();
    }

    private async Task OnAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        await Task.CompletedTask;
    }
}

@namespace sv_b985c205cecf4e88a5cd5b7a82469a36.Components.Pages

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h5 class="product-name">@Product.Name</h5>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <span class="product-rating">@GetStarRating(Product.Rating)</span>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

.price-input {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.25rem;
    margin-bottom: 0.5rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.catalog-toolbar {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.sort-dropdown {
    padding: 0.4rem;
}

.showing-label {
    margin-left: auto;
    color: #555;
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1rem;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.product-image {
    background: #f0f0f0;
    height: 140px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    margin-bottom: 0.75rem;
    color: #888;
    font-size: 0.85rem;
    text-align: center;
}

.product-info {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.product-name {
    margin: 0;
    font-size: 1rem;
}

.product-price {
    margin: 0;
    font-weight: bold;
    color: #2a7a2a;
}

.product-rating {
    color: #f5a623;
}

.badge-out-of-stock {
    background: #dc3545;
    color: white;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    align-self: flex-start;
}

.btn-add-to-cart {
    margin-top: 0.5rem;
    padding: 0.4rem 0.75rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: white;
    cursor: pointer;
}

.btn-add-to-cart:disabled {
    background: #aaa;
    cursor: not-allowed;
}

.pagination {
    display: flex;
    gap: 0.4rem;
    margin-top: 1.5rem;
    justify-content: center;
    flex-wrap: wrap;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

.btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.catalog-status {
    padding: 2rem;
    text-align: center;
    color: #666;
    font-size: 1.1rem;
}

.catalog-status.error {
    color: #dc3545;
}

.btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

