}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.filter-section {
    margin-bottom: 1.25rem;
}

