{"path": "/tmp/sv-b985c205cecf4e88a5cd5b7a82469a36/Components/Pages/Catalog.razor", "file_text": "@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <label>
                Min:
                <input type="number" step="0.01" min="0" @bind="minPrice" class="price-input" />
            </label>
            <label>
                Max:
                <input type="number" step="0.01" min="0" @bind="maxPrice" class="price-input" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-status">Loading products...</div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-status error">@errorMessage</div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-status">No products found.</div>
        }
        else
        {
            <div class="catalog-toolbar">
                <select class="sort-dropdown" @onchange="OnSortChanged">
                    <option value="price_asc" selected="@(sortBy == "price_asc")">Price: Low to High</option>
                    <option value="price_desc" selected="@(sortBy == "price_desc")">Price: High to Low</option>
                    <option value="name_asc" selected="@(sortBy == "name_asc")">Name: A-Z</option>
                    <option value="rating_desc" selected="@(sortBy == "rating_desc")">Rating: Highest</option>
                </select>

                <span class="showing-label">
                    Showing @((result.Page - 1) * result.PageSize + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount)) of @result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="OnProductSelected"
                                 OnAddToCart="OnAddToCart" />
                }
            </div>

            <div class="pagination">
                <button class="btn btn-page" disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn btn-page @(pageNum == currentPage ? "active" : "")"
                            @onclick="() => GoToPage(pageNum)">@pageNum</button>
                }

                <button class="btn btn-page" disabled="@(currentPage >= totalPages)" @onclick="NextPage">Next</button>
            </div>
        }
    </main>
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalPages = 1;
    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            categories = await ProductService.GetCategoriesAsync();
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
            totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
            if (totalPages < 1) totalPages = 1;
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchProducts();
    }

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await SearchProducts();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < totalPages)
        {
            currentPage++;
            await SearchProducts();
        }
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await SearchProducts();
    }

    private async Task OnAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        await Task.CompletedTask;
    }
}
"}

