toolArgs.file_text:
.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

.price-input {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.25rem;
    margin-bottom: 0.5rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.catalog-toolbar {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.sort-dropdown {
    padding: 0.4rem;
}

.showing-label {
    margin-left: auto;
    color: #555;
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1rem;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.product-image {
    background: #f0f0f0;
    height: 140px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    margin-bottom: 0.75rem;
    color: #888;
    font-size: 0.85rem;
    text-align: center;
}

.product-info {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.product-name {
    margin: 0;
    font-size: 1rem;
}

.product-price {
    margin: 0;
    font-weight: bold;
    color: #2a7a2a;
}

.product-rating {
    color: #f5a623;
}

.badge-out-of-stock {
    background: #dc3545;
    color: white;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    align-self: flex-start;
}

.btn-add-to-cart {
    margin-top: 0.5rem;
    padding: 0.4rem 0.75rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: white;
    cursor: pointer;
}

.btn-add-to-cart:disabled {
    background: #aaa;
    cursor: not-allowed;
}

.pagination {
    display: flex;
    gap: 0.4rem;
    margin-top: 1.5rem;
    justify-content: center;
    flex-wrap: wrap;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

.btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.catalog-status {
    padding: 2rem;
    text-align: center;
    color: #666;
    font-size: 1.1rem;
}

.catalog-status.error {
    color: #dc3545;
}

.btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

